/* Strict display reset for hidden elements */
[hidden] {
  display: none !important;
}

:root {
  --color-bg: #181425;
  --color-panel: #262b44;
  --color-panel-border: #3a4466;
  --color-accent: #f4b41b;
  --color-accent-press: #d2940e;
  --color-text-main: #f2f4f8;
  --color-text-dim: #9da9ba;
  --color-shadow: #100c1e;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: 'Courier New', Courier, monospace, system-ui, sans-serif;
  font-size: 16px;
  line-height: 1.4;
  background-color: var(--color-bg);
  color: var(--color-text-main);
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
  background-image:
    linear-gradient(45deg, #1f1b33 25%, transparent 25%),
    linear-gradient(-45deg, #1f1b33 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, #1f1b33 75%),
    linear-gradient(-45deg, transparent 75%, #1f1b33 75%);
  background-size: 24px 24px;
  background-position: 0 0, 0 12px, 12px -12px, -12px 0;
}

.quiz-board {
  width: 100%;
  max-width: 640px;
  min-width: 320px;
  background: var(--color-panel);
  border: 4px solid var(--color-panel-border);
  box-shadow: 6px 6px 0px var(--color-shadow);
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.quiz-header {
  border-bottom: 4px dashed var(--color-panel-border);
  padding-bottom: 16px;
}

.pixel-title {
  font-size: 28px;
  text-align: center;
  letter-spacing: 2px;
  color: var(--color-accent);
  text-shadow: 3px 3px 0px var(--color-shadow);
  margin-bottom: 16px;
}

.status-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
}

.status-item {
  background: var(--color-bg);
  border: 3px solid var(--color-panel-border);
  padding: 8px 14px;
  font-weight: bold;
  font-size: 18px;
  box-shadow: 2px 2px 0px var(--color-shadow);
}

.status-label {
  color: var(--color-text-dim);
  margin-right: 4px;
}

.status-value {
  color: var(--color-accent);
}

.question-meta {
  font-size: 16px;
  color: var(--color-text-dim);
  margin-bottom: 8px;
  font-weight: bold;
}

.question-card {
  background: var(--color-bg);
  border: 3px solid var(--color-panel-border);
  padding: 20px;
  min-height: 90px;
  display: flex;
  align-items: center;
  margin-bottom: 20px;
  box-shadow: 3px 3px 0px var(--color-shadow);
}

.question-heading {
  font-size: 18px;
  font-weight: bold;
  color: var(--color-text-main);
}

.answers-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 12px;
}

@media (min-width: 500px) {
  .answers-grid {
    grid-template-columns: 1fr 1fr;
  }
}

.pixel-btn {
  appearance: none;
  font-family: inherit;
  font-size: 16px;
  font-weight: bold;
  background-color: var(--color-panel);
  color: var(--color-text-main);
  border: 3px solid var(--color-text-main);
  padding: 14px 16px;
  cursor: pointer;
  text-align: left;
  box-shadow: 4px 4px 0px var(--color-shadow);
  transition: none;
}

.pixel-btn:hover {
  background-color: var(--color-accent);
  color: var(--color-bg);
  border-color: var(--color-text-main);
}

.pixel-btn:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 3px;
}

.pixel-btn:active {
  transform: translate(2px, 2px);
  box-shadow: 2px 2px 0px var(--color-shadow);
}

/* End Screen Styles */
.result-card {
  text-align: center;
  padding: 24px 12px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
}

.end-title {
  font-size: 26px;
  color: var(--color-accent);
  text-shadow: 2px 2px 0px var(--color-shadow);
}

.end-reason {
  font-size: 18px;
  color: var(--color-text-dim);
}

.final-score-display {
  background: var(--color-bg);
  border: 3px solid var(--color-panel-border);
  padding: 16px 28px;
  font-size: 20px;
  font-weight: bold;
  display: flex;
  flex-direction: column;
  gap: 6px;
  box-shadow: 3px 3px 0px var(--color-shadow);
}

.highlight-val {
  font-size: 32px;
  color: var(--color-accent);
}

.play-again-btn {
  text-align: center;
  background-color: var(--color-accent);
  color: var(--color-bg);
  padding: 14px 28px;
  margin-top: 8px;
}

.play-again-btn:hover {
  background-color: var(--color-accent-press);
  color: var(--color-bg);
}

document.addEventListener('DOMContentLoaded', () => {
  const QUIZ_QUESTIONS = [
    {
      question: "Which HTML element is used to include pure JavaScript?",
      options: ["<javascript>", "<script>", "<js>", "<code>"],
      correctIndex: 1
    },
    {
      question: "Which CSS selector targets elements with the 'hidden' attribute?",
      options: ["[hidden]", ".hidden", "#hidden", ":hidden"],
      correctIndex: 0
    },
    {
      question: "In a browser, what is the default event dispatch mechanism?",
      options: ["Polling", "Capturing & Bubbling", "Broadcasting only", "Thread Pooling"],
      correctIndex: 1
    },
    {
      question: "How many bits typically represent a single byte in retro hardware?",
      options: ["4 bits", "8 bits", "16 bits", "32 bits"],
      correctIndex: 1
    },
    {
      question: "Which method registers a user event without inline HTML attributes?",
      options: ["attachHandler()", "onEvent()", "addEventListener()", "registerAction()"],
      correctIndex: 2
    }
  ];

  const TOTAL_TIME = 60;
  let timeLeft = TOTAL_TIME;
  let timerInterval = null;
  let currentQuestionIndex = 0;
  let currentScore = 0;

  // Elements
  const timerDisplay = document.getElementById('timer-display');
  const scoreDisplay = document.getElementById('score-display');
  const gameScreen = document.getElementById('game-screen');
  const endScreen = document.getElementById('end-screen');
  const questionCounter = document.getElementById('question-counter');
  const questionText = document.getElementById('question-text');
  const answerButtons = Array.from(document.querySelectorAll('.answer-btn'));
  const endReason = document.getElementById('end-reason');
  const finalScoreVal = document.getElementById('final-score-val');
  const restartBtn = document.getElementById('restart-btn');

  function startTimer() {
    clearInterval(timerInterval);
    timeLeft = TOTAL_TIME;
    timerDisplay.textContent = timeLeft;

    timerInterval = setInterval(() => {
      timeLeft -= 1;
      timerDisplay.textContent = timeLeft;

      if (timeLeft <= 0) {
        clearInterval(timerInterval);
        endQuiz('Time is up!');
      }
    }, 1000);
  }

  function loadQuestion(index) {
    const q = QUIZ_QUESTIONS[index];
    questionCounter.textContent = `Question ${index + 1} of ${QUIZ_QUESTIONS.length}`;
    questionText.textContent = q.question;

    answerButtons.forEach((btn, idx) => {
      btn.textContent = `${String.fromCharCode(65 + idx)}. ${q.options[idx]}`;
    });
  }

  function handleAnswer(selectedIndex) {
    const q = QUIZ_QUESTIONS[currentQuestionIndex];
    if (selectedIndex === q.correctIndex) {
      currentScore += 20;
      scoreDisplay.textContent = currentScore;
    }

    currentQuestionIndex += 1;
    if (currentQuestionIndex < QUIZ_QUESTIONS.length) {
      loadQuestion(currentQuestionIndex);
    } else {
      endQuiz('All questions answered!');
    }
  }

  function endQuiz(reason) {
    clearInterval(timerInterval);
    gameScreen.hidden = true;
    endScreen.hidden = false;
    endReason.textContent = reason;
    finalScoreVal.textContent = currentScore;
    restartBtn.focus();
  }

  function resetGame() {
    currentScore = 0;
    currentQuestionIndex = 0;
    scoreDisplay.textContent = currentScore;
    endScreen.hidden = true;
    gameScreen.hidden = false;
    loadQuestion(0);
    startTimer();
    if (answerButtons.length > 0) {
      answerButtons[0].focus();
    }
  }

  answerButtons.forEach((btn) => {
    btn.addEventListener('click', (e) => {
      const selectedIndex = parseInt(e.currentTarget.getAttribute('data-index'), 10);
      handleAnswer(selectedIndex);
    });
  });

  restartBtn.addEventListener('click', resetGame);

  // Initial boot
  resetGame();
});
